document.addEventListener(`DOMContentLoaded`,()=>{e(),t()});function e(){let e=document.querySelectorAll(`.cs-content-section, #overview, #problem, #role, #process, #solution, #results`),t=document.querySelectorAll(`.cs-nav-tab`);if(!e.length||!t.length)return;let n=new IntersectionObserver(e=>{e.forEach(e=>{if(e.isIntersecting){let n=e.target.getAttribute(`id`);t.forEach(e=>{e.getAttribute(`href`)===`#${n}`?e.classList.add(`active`):e.classList.remove(`active`)})}})},{root:null,rootMargin:`-120px 0px -60% 0px`,threshold:0});e.forEach(e=>n.observe(e))}function t(){document.querySelectorAll(`.cs-nav-tab, .cs-summary-btn`).forEach(e=>{e.addEventListener(`click`,t=>{let n=e.getAttribute(`href`);if(n&&n.startsWith(`#`)){let r=document.querySelector(n);if(r){t.preventDefault();let n=r.getBoundingClientRect().top+window.pageYOffset-120;window.scrollTo({top:n,behavior:`smooth`}),document.querySelectorAll(`.cs-nav-tab`).forEach(e=>e.classList.remove(`active`)),e.classList.contains(`cs-nav-tab`)&&e.classList.add(`active`)}}})})}